package com.qualitypilot.campaignlab.execution;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"run_id","user_id"})) public class UserJourney{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="run_id")private String runId;@Column(name="user_id")private String userId;@Enumerated(EnumType.STRING)private RunStatus status;@Column(name="started_at")private Instant startedAt;protected UserJourney(){}public UserJourney(String runId,String userId,Instant now){this.runId=runId;this.userId=userId;startedAt=now;status=RunStatus.RUNNING;}public String getRunId(){return runId;}public String getUserId(){return userId;}public RunStatus getStatus(){return status;}public void waiting(){status=RunStatus.WAITING;}public void succeeded(){status=RunStatus.SUCCEEDED;}}
